{
  "interpretation": {
    "name": "ProvideNutrunnerToLine2",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Reserve the shared nutrunner NR7, use it for the F30 tightening at station st2 on line 2, and return it to the crib so line 3 can have it.",
    "constraints": [
      "NR7 must be reserved before any use and released after it is back in the crib",
      "NR7 must be at st2 before configure-tool and tighten-fasteners",
      "transport-tool must be delegated to agvexecutor",
      "The tightening program must come from get-program, with no numeric process values in the Recipe",
      "The tightening must be evaluated and recorded",
      "The lease must be renewed before every tool-using Step, so those Steps depend on reserve-tool"
    ],
    "preference": "Minimise the time NR7 is away from the crib: get the program while the AGV is moving, return the tool right after tightening, and run evaluation and recording in parallel with the return transport.",
    "priority": "high",
    "horizon": "Single execution, immediate",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nutrunner-tightening-f30",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Tighten",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": ["transport-to-station", "fetch-program"],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          },
          {
            "name": "fetch-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Tighten",
        "next": "ReturnAndClose",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten"],
            "dep": ["reserve", "fetch-program", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["reserve", "configure"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "ReturnAndClose",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve", "transport-to-crib"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten", "fetch-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
